/** Exact equality for private natural-order journal views, without tree lookups. */
private static boolean sameView(SortedMap<Long,String> left,SortedMap<Long,String> right){
    if(left.size()!=right.size())return false;
    Iterator<Map.Entry<Long,String>> a=left.entrySet().iterator(),b=right.entrySet().iterator();
    while(a.hasNext()){
        Map.Entry<Long,String> x=a.next(),y=b.next();
        if(!x.getKey().equals(y.getKey())||!Objects.equals(x.getValue(),y.getValue()))return false;
    }
    return true;
}
